+func epssScore(es []EPSS) float64 {
+	if len(es) == 0 {
+		return 0.0
+	}
+	maxScore := es[0].EPSS
+	for _, e := range es[1:] {
+		if e.EPSS > maxScore {
+			maxScore = e.EPSS
+		}
+	}
+	return maxScore
